 struct vkctx c;const char*ex[]={"VK_KHR_portability_subset"};vkctx_init(&c,0,ex,1);VkPhysicalDeviceProperties props;vkGetPhysicalDeviceProperties(c.physical,&props);printf("maxBoundDescriptorSets=%u requested=%u\n",props.limits.maxBoundDescriptorSets,hi+1);
